    console.error(`Failed to read package.json: ${err instanceof Error ? err.message : err}`);
    process.exit(1);
  }

  const pkg = JSON.parse(content) as { version?: string };
  if (!pkg.version) {
    console.error('No "version" field found in package.json');
    process.exit(1);
  }

  return pkg.version;
}

function getConstantsVersion(): string {
  const constantsPath = path.join(__dirname, '..', 'src', 'core', 'constants.ts');
  let content: string;
  try {
    content = readFileSync(constantsPath, 'utf-8');
  } catch (err) {
    console.error(`Failed to read constants.ts: ${err instanceof Error ? err.message : err}`);
    process.exit(1);
  }

  const match = content.match(/PACKAGE_VERSION\s*=\s*['"]([^'"]+)['"]/);
  if (!match) {
    console.error('Could not find PACKAGE_VERSION in constants.ts');
    process.exit(1);
